create unique index if not exists kos_document_links_company_unique on public.kos_document_links(workspace_id, document_id, resource_type, resource_id, relationship) where resource_type = 'company';
create or replace function public.kos_assign_document_company(target_workspace uuid,target_document uuid,target_company uuid) returns public.kos_document_links language plpgsql security definer set search_path=public as $$ declare actor uuid:=auth.uid(); created public.kos_document_links; begin if actor is null or not public.kos_has_role(target_workspace,array['owner','admin','member']::public.kos_workspace_role[]) then raise exception 'workspace write access required'; end if; if not exists(select 1 from public.kos_documents where id=target_document and workspace_id=target_workspace) then raise exception 'document not found in workspace'; end if; if not exists(select 1 from public.kos_companies where id=target_company and workspace_id=target_workspace) then raise exception 'company not found in workspace'; end if; delete from public.kos_document_links where workspace_id=target_workspace and document_id=target_document and resource_type='company'; insert into public.kos_document_links(workspace_id,document_id,resource_type,resource_id,relationship) values(target_workspace,target_document,'company',target_company,'filed_under') returning * into created; return created; end; $$;
revoke all on function public.kos_assign_document_company(uuid,uuid,uuid) from public,anon;
grant execute on function public.kos_assign_document_company(uuid,uuid,uuid) to authenticated;
